-- Cross-check of two marine cooling/seawater parts found in Cat sample parts catalog
-- hosted by engine.od.ua, then checked against the current Cat Parts Store pages.
-- These remain reference-only; no price or stock is inferred.
insert into public.part_catalog
 (part_number,name,description,engine_models,technical_group,source_name,source_url,source_note,verification_status,application_type,application_evidence,application_source_url)
values
('5B-9169','پلاگ رزوه‌ای Cat 5B-9169','1/2-14 NPTF threaded pipe plug. The Cat 3608 sample parts catalog lists this part in the Auxiliary Sea Water lines groups 2W-2760 and 122-4947 (quantity 1 in each listed group). Cat Parts Store separately lists Marine Engine and multiple non-marine compatible equipment classes.','{D353E,D334,D337,D336,3116,D353C,D353D,C18,D315,3126B,C12,D379A,D379B,C15,D399,3208,D330A,D330B,D342C,3306B,D333A,D333B,C30,D333C,C32,D397D,3408B,3408C,3304,3412E,3306,3412D,3304B,D364,3412,D375D,3406B,3406C,3406E,C7,D349,3408,D346,D348,3406,D398A,D398B,3126,D342,D343}','موتورهای دریایی - خنک‌کاری و آب دریا - پلاگ رزوه‌ای','Cat Parts Store + Cat parts-catalog sample hosted by engine.od.ua','https://parts.cat.com/en/catcorp/product/5B-9169','Cat sample document SEBP3780-67, 3608 Generator/Industrial/Locomotive/Marine, serial 6NC1-UP, pages 1-2: part 5B-9169 is listed in Auxiliary Sea Water lines groups 2W-2760 and 122-4947. Cat Parts Store Compatible Models independently lists Marine Engine and non-marine equipment classes. This does not establish fitment to every 3608 serial number.','REFERENCE','BOTH','Cat Parts Store Compatible Models lists Marine Engine and multiple non-marine classes. The sample parts catalog additionally places the part in Auxiliary Sea Water groups.','https://parts.cat.com/en/catcorp/product/5B-9169'),
('6L-2288','میله آند روی Cat 6L-2288','3/8-inch zinc anode, 76.2 mm long. The Cat 3608 sample parts catalog lists this part in Auxiliary Sea Water lines groups 2W-2760 and 122-4947 (quantity 1 in each listed group). Cat Parts Store lists Marine Engine and non-marine Gen Set/Industrial/Gas Engine compatible classes; its listing includes 3608 under Gen Set Engine, not Marine Engine.','{D353E,D336,D353C,D353D,3126B,D379A,D379B,D399,C7,D349,D346,D348,3406,D398A,D398B,D342C,D342,D343,3208}','موتورهای دریایی - خنک‌کاری و آب دریا - آند روی','Cat Parts Store + Cat parts-catalog sample hosted by engine.od.ua','https://parts.cat.com/en/catcorp/product/6L-2288','Cat sample document SEBP3780-67, 3608 Generator/Industrial/Locomotive/Marine, serial 6NC1-UP, pages 1-2: part 6L-2288 is listed in Auxiliary Sea Water lines groups 2W-2760 and 122-4947. Cat Parts Store independently lists Marine Engine and non-marine classes; 3608 appears under Gen Set Engine, not Marine Engine, so no 3608 marine-engine fitment is asserted.','REFERENCE','BOTH','Cat Parts Store Compatible Models lists Marine Engine and non-marine Gen Set Engine/Industrial/Gas Engine classes. Marine fitment for 3608 specifically is not asserted.','https://parts.cat.com/en/catcorp/product/6L-2288')
on conflict (part_number) do update set
 name=excluded.name,description=excluded.description,engine_models=excluded.engine_models,
 technical_group=excluded.technical_group,source_name=excluded.source_name,
 source_url=excluded.source_url,source_note=excluded.source_note,
 verification_status='REFERENCE',application_type=excluded.application_type,
 application_evidence=excluded.application_evidence,
 application_source_url=excluded.application_source_url,updated_at=now();
